#!/bin/sh
# Print the 3 most frequent IPs from access.log, most frequent first,
# ties broken by first appearance in the log.
awk '
{
    ip = $1
    if (!(ip in count)) {
        order[++n] = ip
    }
    count[ip]++
}
END {
    for (i = 1; i <= 3; i++) {
        best = 0
        for (j = 1; j <= n; j++) {
            ip = order[j]
            if (picked[ip]) continue
            if (best == 0 || count[ip] > count[order[best]]) best = j
        }
        picked[order[best]] = 1
        print order[best]
    }
}' access.log
